"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["6207"],{71315(e){e.exports=JSON.parse('{"id":"V4-055","slug":"seigniorage","term":"Seigniorage","also_known_as":[],"difficulty":"Advanced","definition":"Seigniorage is the profit a government or central bank earns from issuing money, equal to the difference between the value of money created and the cost of producing and distributing it.","explanation":["Producing a banknote costs only a small amount, but it can buy goods and services worth far more. The difference is seigniorage. The term comes from the historical right of feudal lords, called seigneurs, to mint coins.","In modern economies, seigniorage arises mainly because central banks issue banknotes and hold reserves on which they pay little or no interest, while holding interest-earning assets, such as government bonds. The income from these assets, after costs, is usually passed to the government.","For example, if people hold 100 billion in banknotes, which pay no interest, and the central bank holds bonds earning 3%, it earns about 3 billion a year from this arrangement.","Seigniorage can be an important source of government revenue, but relying on it too heavily, by printing money to finance spending, can cause high inflation or hyperinflation. Countries that use another country\u2019s currency, through dollarization, give up their seigniorage to the issuing country. As cash use declines, seigniorage from banknotes is shrinking."],"note":"","total":1725,"prev":{"slug":"segregation-of-duties","term":"Segregation of Duties"},"next":{"slug":"selection-bias","term":"Selection Bias"}}')}}]);